CREATE TABLE IF NOT EXISTS schema_migrations(version integer PRIMARY KEY, applied_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS research_settings(project_id text PRIMARY KEY, retention_days integer NOT NULL DEFAULT 90 CHECK(retention_days BETWEEN 1 AND 730), idle_ms integer NOT NULL DEFAULT 120000, method_version text NOT NULL DEFAULT 'active-v1', consent_version text NOT NULL DEFAULT 'research-v1');
CREATE TABLE IF NOT EXISTS research_participants(id uuid PRIMARY KEY, project_id text NOT NULL REFERENCES research_settings(project_id), created_at timestamptz NOT NULL DEFAULT now(), deletion_status text NOT NULL DEFAULT 'active');
CREATE TABLE IF NOT EXISTS consent_grants(code_hash text PRIMARY KEY, project_id text NOT NULL REFERENCES research_settings(project_id), version text NOT NULL, scope text NOT NULL, method text NOT NULL, expires_at timestamptz NOT NULL, used_at timestamptz);
CREATE TABLE IF NOT EXISTS research_consents(id uuid PRIMARY KEY, participant_id uuid NOT NULL REFERENCES research_participants(id) ON DELETE CASCADE, version text NOT NULL, scope text NOT NULL, method text NOT NULL, status text NOT NULL DEFAULT 'active', granted_at timestamptz NOT NULL DEFAULT now(), withdrawn_at timestamptz);
CREATE TABLE IF NOT EXISTS consent_tombstones(consent_id uuid PRIMARY KEY, blocked_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS participant_tokens(token_hash text PRIMARY KEY, participant_id uuid NOT NULL REFERENCES research_participants(id) ON DELETE CASCADE, consent_id uuid NOT NULL REFERENCES research_consents(id) ON DELETE CASCADE, expires_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS reader_sessions(id uuid PRIMARY KEY, participant_id uuid NOT NULL REFERENCES research_participants(id) ON DELETE CASCADE, started_at timestamptz NOT NULL, last_seen_at timestamptz NOT NULL DEFAULT now(), content_version text NOT NULL);
CREATE TABLE IF NOT EXISTS reading_runs(id uuid PRIMARY KEY, session_id uuid NOT NULL REFERENCES reader_sessions(id) ON DELETE CASCADE, started_at timestamptz NOT NULL, completed_at timestamptz, route text, ending text);
CREATE TABLE IF NOT EXISTS telemetry_events(event_id uuid PRIMARY KEY, project_id text NOT NULL REFERENCES research_settings(project_id), book_id text NOT NULL, content_version text NOT NULL, participant_id uuid NOT NULL REFERENCES research_participants(id) ON DELETE CASCADE, session_id uuid NOT NULL REFERENCES reader_sessions(id) ON DELETE CASCADE, run_id uuid NOT NULL REFERENCES reading_runs(id) ON DELETE CASCADE, consent_id uuid NOT NULL REFERENCES research_consents(id) ON DELETE CASCADE, event_schema_version integer NOT NULL CHECK(event_schema_version=1), sequence integer NOT NULL, event_name text NOT NULL, page_id text, step_id text, client_ts timestamptz NOT NULL, received_at timestamptz NOT NULL DEFAULT now(), payload jsonb NOT NULL);
CREATE INDEX IF NOT EXISTS events_received ON telemetry_events(received_at);
CREATE INDEX IF NOT EXISTS events_scope_version ON telemetry_events(project_id,content_version,received_at);
CREATE INDEX IF NOT EXISTS events_session_sequence ON telemetry_events(session_id,sequence);
CREATE INDEX IF NOT EXISTS events_name_page ON telemetry_events(event_name,page_id);
CREATE INDEX IF NOT EXISTS events_page_visit ON telemetry_events((payload->>'page_visit_id'));
CREATE UNIQUE INDEX IF NOT EXISTS events_interval_unique ON telemetry_events(session_id,(payload->>'interval_id')) WHERE event_name='page_activity';
CREATE TABLE IF NOT EXISTS admin_users(id uuid PRIMARY KEY, project_id text NOT NULL REFERENCES research_settings(project_id), username text NOT NULL UNIQUE, password_hash text NOT NULL, role text NOT NULL DEFAULT 'admin');
CREATE TABLE IF NOT EXISTS admin_sessions(token_hash text PRIMARY KEY, admin_id uuid NOT NULL REFERENCES admin_users(id) ON DELETE CASCADE, expires_at timestamptz NOT NULL, csrf text NOT NULL);
CREATE TABLE IF NOT EXISTS admin_audit_log(id uuid PRIMARY KEY, admin_id uuid REFERENCES admin_users(id) ON DELETE SET NULL, project_id text NOT NULL, action text NOT NULL, target_id text, created_at timestamptz NOT NULL DEFAULT now());
INSERT INTO schema_migrations(version) VALUES(1) ON CONFLICT DO NOTHING;
